-- =============================================================================
-- 3D Studio: try a creation on a smile photo with AI (decision 111, owner's request 2026-10-25)
-- =============================================================================
-- "Let me try a creation on a smile with Google's Nano Banana 2 — I will
-- connect it later; the request flow must be easy; clients must be able to
-- try the artist's creations easily; in time only artists on the highest plan
-- will have the option for their 3D creations."
--
-- The image is generated by the Edge Function `studio-try-on` (the provider's
-- key never reaches the browser). This migration gives it what it must decide
-- on the server:
--
--   1. The plan switch, private.studio_try_on_allowed(owner): whether the
--      creations of a given ARTIST may be tried on. It is the owner's plan
--      that counts, never the visitor's (a Glowbook visitor may have no
--      account at all). Today: every member with Studio access (owner's
--      decision: open for now); later one line, `studio_user_tier(owner) =
--      'atelier'`.
--   2. The flag on the two public readers (Glowbook creation, share link),
--      so a viewer shows "Try it on my smile" only where it may be used —
--      without ever exposing the owner's id.
--   3. studio_try_on_creation(): the function's only door to a creation,
--      by exactly one reference (the requester's own creation, an active
--      share token, or an approved Glowbook item), with the owner's switch.
--      The scene sent to the AI is read here, never taken from the browser.
--   4. studio_try_on_requests: one row per generation asked (no photo, no
--      image), for the daily limit and the cost follow-up.
--   5. The private bucket `studio-try-on-references`: the reference pictures
--      the owner uploads from the dashboard for the AI call. No policy: only
--      the service role (the function) and the dashboard read it.
--
-- The smile photo and the generated image are never stored.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. The plan switch
-- -----------------------------------------------------------------------------
create or replace function private.studio_try_on_allowed(p_owner uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  -- Open to every member with Studio access for now (owner's decision, 2026-10-25).
  -- To reserve it to the highest plan: coalesce(private.studio_user_tier(p_owner) = 'atelier', false).
  select coalesce(private.studio_user_has_access(p_owner), false);
$$;

comment on function private.studio_try_on_allowed(uuid) is
  '3D Studio smile try-on (decision 111): whether the creations of this owner may be tried on a photo. Today: Studio access; later the highest plan.';

revoke all on function private.studio_try_on_allowed(uuid) from public;
grant execute on function private.studio_try_on_allowed(uuid) to service_role;

-- -----------------------------------------------------------------------------
-- 2. The flag on the public readers
-- -----------------------------------------------------------------------------
create or replace function public.studio_public_showcase_creation(p_handle text, p_item_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
           'handle', s.handle,
           'display_name', s.display_name,
           'name', c.name,
           'description', c.description,
           'scene_data', c.scene_data || jsonb_build_object(
             'groups', coalesce((
               select jsonb_agg(g || jsonb_build_object('gemGroupId', null))
                 from jsonb_array_elements(case when jsonb_typeof(c.scene_data -> 'groups') = 'array'
                                                then c.scene_data -> 'groups' else '[]'::jsonb end) g
             ), '[]'::jsonb)),
           'updated_at', c.updated_at,
           'try_on', private.studio_try_on_allowed(s.user_id))
    from public.studio_showcases s
    join public.studio_showcase_items i on i.user_id = s.user_id and i.id = p_item_id and i.status = 'approved'
    join public.creations c on c.id = i.creation_id
   where s.handle = lower(btrim(p_handle))
     and s.status = 'approved'
     and private.studio_user_has_access(s.user_id);
$$;

comment on function public.studio_public_showcase_creation(text, uuid) is
  '3D Studio Glowbook: one approved creation of a public Glowbook, with its scene and whether it may be tried on a photo (decision 111), for the read-only 3D viewer; null otherwise. No owner id or personal data.';

-- The return type gains a column: drop and recreate (same body otherwise).
drop function public.studio_shared_creation(text);

create function public.studio_shared_creation(p_token text)
returns table (name text, description text, scene_data jsonb, updated_at timestamptz, try_on boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select c.name,
         c.description,
         case
           when jsonb_typeof(c.scene_data -> 'groups') = 'array' then
             jsonb_set(c.scene_data, '{groups}', (
               select coalesce(jsonb_agg(case when jsonb_typeof(g) = 'object'
                                              then g || jsonb_build_object('gemGroupId', null)
                                              else g end), '[]'::jsonb)
                 from jsonb_array_elements(c.scene_data -> 'groups') as g))
           else c.scene_data
         end,
         c.updated_at,
         private.studio_try_on_allowed(c.user_id)
    from public.creation_shares s
    join public.creations c on c.id = s.creation_id
   where coalesce(p_token, '') ~ '^[0-9a-f]{48}$'
     and s.token = p_token
     and s.revoked_at is null;
$$;

comment on function public.studio_shared_creation(text) is
  '3D Studio share link: the shared creation (name, description, scene, whether it may be tried on a photo — decision 111) behind an active token; nothing about its owner.';

revoke all on function public.studio_shared_creation(text) from public, anon, authenticated;
grant execute on function public.studio_shared_creation(text) to anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- 3. The Edge Function's door to a creation
-- -----------------------------------------------------------------------------
-- Exactly one reference: p_creation_id (the requester's own creation),
-- p_token (an active share link) or p_handle + p_item_id (an approved item of
-- a public Glowbook, same rule as studio_public_showcase_creation). Returns
-- { creation_id, source, name, scene_data, allowed } or null when the
-- reference matches nothing the requester may see. Service role only.
create or replace function public.studio_try_on_creation(
  p_requester uuid,
  p_creation_id uuid default null,
  p_token text default null,
  p_handle text default null,
  p_item_id uuid default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_refs int := (p_creation_id is not null)::int + (p_token is not null)::int
              + (p_handle is not null or p_item_id is not null)::int;
  v_row jsonb;
begin
  if p_requester is null or v_refs <> 1 then
    return null;
  end if;

  if p_creation_id is not null then
    select jsonb_build_object('creation_id', c.id, 'source', 'own', 'name', c.name, 'scene_data', c.scene_data,
                              'allowed', private.studio_try_on_allowed(c.user_id))
      into v_row
      from public.creations c
     where c.id = p_creation_id and c.user_id = p_requester;
  elsif p_token is not null then
    select jsonb_build_object('creation_id', c.id, 'source', 'share', 'name', c.name, 'scene_data', c.scene_data,
                              'allowed', private.studio_try_on_allowed(c.user_id))
      into v_row
      from public.creation_shares s
      join public.creations c on c.id = s.creation_id
     where p_token ~ '^[0-9a-f]{48}$' and s.token = p_token and s.revoked_at is null;
  elsif p_handle is not null and p_item_id is not null then
    select jsonb_build_object('creation_id', c.id, 'source', 'glowbook', 'name', c.name, 'scene_data', c.scene_data,
                              'allowed', private.studio_try_on_allowed(s.user_id))
      into v_row
      from public.studio_showcases s
      join public.studio_showcase_items i on i.user_id = s.user_id and i.id = p_item_id and i.status = 'approved'
      join public.creations c on c.id = i.creation_id
     where s.handle = lower(btrim(p_handle))
       and s.status = 'approved'
       and private.studio_user_has_access(s.user_id);
  end if;

  return v_row;
end;
$$;

comment on function public.studio_try_on_creation(uuid, uuid, text, text, uuid) is
  '3D Studio smile try-on (decision 111): the creation a requester may try on, by one reference (own id, share token, Glowbook item), with the owner''s plan switch. Service role only (Edge Function studio-try-on).';

revoke all on function public.studio_try_on_creation(uuid, uuid, text, text, uuid) from public, anon, authenticated;
grant execute on function public.studio_try_on_creation(uuid, uuid, text, text, uuid) to service_role;

-- -----------------------------------------------------------------------------
-- 4. Requests (daily limit, cost follow-up)
-- -----------------------------------------------------------------------------
create table public.studio_try_on_requests (
  id           uuid primary key default gen_random_uuid(),
  -- CASCADE: the requests are the member's own usage and go with the account.
  user_id      uuid not null references public.profiles (id) on delete cascade,
  -- SET NULL: the count must survive the artist deleting the creation.
  creation_id  uuid references public.creations (id) on delete set null,
  source       text not null check (source in ('own', 'share', 'glowbook')),
  status       text not null default 'pending' check (status in ('pending', 'generated', 'failed')),
  error_code   text check (error_code is null or char_length(error_code) <= 40),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

comment on table public.studio_try_on_requests is
  '3D Studio smile try-on (decision 111): one row per AI generation asked, written by the Edge Function only. Never the photo nor the image.';

create index studio_try_on_requests_user_created_idx on public.studio_try_on_requests (user_id, created_at desc);
create index studio_try_on_requests_creation_idx on public.studio_try_on_requests (creation_id);

alter table public.studio_try_on_requests enable row level security;

-- A member reads their own requests; nobody writes from the browser.
create policy studio_try_on_requests_select_own on public.studio_try_on_requests
  for select to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.studio_try_on_requests from anon, authenticated;
grant select on public.studio_try_on_requests to authenticated;
grant select, insert, update on public.studio_try_on_requests to service_role;

create trigger studio_try_on_requests_set_updated_at
  before update on public.studio_try_on_requests
  for each row execute function private.set_updated_at();

-- -----------------------------------------------------------------------------
-- 5. Reference pictures for the AI (filled by the owner)
-- -----------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('studio-try-on-references', 'studio-try-on-references', false, 10485760,
        array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;
-- No storage.objects policy on purpose: only the service role and the dashboard.
